/**
 * CHK is a flat stream of chunks: 4-byte name, int32 length, then that many bytes.
 *
 * StarCraft applies chunks *sequentially into fixed-size buffers*, so a section that
 * appears twice is not "last one wins" — the later copy overwrites only as many bytes
 * as it carries. Protected maps lean on this constantly, so the reader keeps every
 * occurrence in file order and `layer()` reproduces the overwrite semantics.
 */
export interface ChkSection {
	/** 4-character chunk name, latin1. May contain junk in protected maps. */
	name: string;
	/** Byte offset of the chunk's *name* within the CHK. */
	offset: number;
	/** Length field as written, which may disagree with `data.length` when truncated. */
	declaredSize: number;
	data: Uint8Array;
	/** Set when the declared size ran past the end of the file. */
	truncated?: boolean;
}
export interface ChkFile {
	sections: ChkSection[];
	/** Bytes after the last parseable chunk header, if any. */
	trailing?: Uint8Array;
}
/**
 * How the game combines repeated occurrences of a section. Which mode applies is a
 * per-section fact (see sections/registry.ts), not something the container can infer.
 */
export type CombineMode = 
/** Zeroed fixed buffer, each occurrence copied over the front in file order. */
"overlay"
/** Every occurrence's records are kept, in file order. */
 | "append"
/** Only the last occurrence is used — of those at least the section's minimum length. */
 | "last"
/** Only the first occurrence is used — of those at least the section's minimum length. */
 | "first"
/**
 * A settings table: each occurrence changes only the entries it marks as not using the
 * game's own values (`EntryLayout`), the rest keep what an earlier one gave them.
 */
 | "entries";
/**
 * The byte encodings a map's text can be in, and how to tell which one a file used.
 *
 * StarEdit wrote the string table in whatever code page Windows was running — EUC-KR
 * (CP949) on a Korean machine, Shift_JIS on a Japanese one, Windows-1252 nearly everywhere
 * else — and 1.16.1 still reads it that way. Remastered writes UTF-8 and, reading, decides
 * per string: UTF-8 when the bytes are valid UTF-8, else Korean when they pass its CP949
 * test, else Windows-1252 (`remasteredReadsAsKorean`). The file itself carries no note of which was used, so a table is *guessed*
 * on open (`detectTextEncoding`) and the guess is a setting the user can correct
 * (Scenario ▸ Map Revision).
 *
 * Decoding is the platform's (`TextDecoder` knows every label here). Encoding is not —
 * `TextEncoder` is UTF-8 only — so each legacy encoding's table is built once, lazily,
 * by decoding every byte and every lead/trail byte pair it has and remembering what came
 * back (`reverseTable`). A character the encoding cannot hold is written as `?`, the
 * way StarEdit's own dialogs did, and `unencodable` lists them so Check Map and the
 * dialog can say so before the file is written.
 */
export type TextEncoding = "utf-8" | "euc-kr" | "shift_jis" | "gbk" | "big5" | "windows-1251" | "windows-1252";
/**
 * STR/STRx string table.
 *
 * Index 0 means "no string" and is never stored. Indices are referenced from TRIG,
 * MRGN, SPRP and friends — several of which we round-trip as raw bytes — so the table
 * must keep its index space stable across a save. Entries are therefore addressed by
 * position, never renumbered.
 *
 * The bytes carry no note of their encoding (see `text/encoding.ts`): `decodeStrings`
 * guesses one from the whole table's bytes unless told, and `encodeStrings` writes the
 * table's, so a file opened and saved keeps its bytes and a Korean file edited on a
 * Korean game stays readable there.
 */
export interface StringTable {
	/** `strings[i]` is string index `i`; slot 0 is always null. */
	strings: (string | null)[];
	/** True when the source section was STRx (Remastered, 32-bit count and offsets). */
	extended: boolean;
	/** How the text is written to bytes; guessed on open, a setting afterwards. */
	encoding: TextEncoding;
}
